# builder/gen_ch18_p3.py
# -*- coding: utf-8 -*-

exercises = [{'num': 67, 'title': 'Валидация заголовка и сигнатуры PNG файла', 'task': 'Напиши программу, которая читает заголовок PNG-файла (первые 8 байт — сигнатура `\\x89PNG\\r\\n\\x1a\\n`). Проверь, что файл действительно PNG.', 'theory': 'Спецификация W3C PNG определяет строгую 8-байтную сигнатуру: `\\x89 P N G \\r \\n \\x1a \\n` (`0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A`). Чтение ровно 8 байт через `io.ReadFull` позволяет валидировать формат файла.', 'step_by_step': '1. Зададим константу сигнатуры PNG.\n2. Создадим валидный PNG заголовок.\n3. Откроем файл и прочитаем первые 8 байт.\n4. Сравним через `bytes.Equal(header, pngSignature)`.\n5. В `main` выведем результат проверки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nvar pngHeader = []byte{0x89, \'P\', \'N\', \'G\', 0x0D, 0x0A, 0x1A, 0x0A}\n\nfunc isPNG(path string) (bool, error) {\n\tfile, err := os.Open(path)\n\tif err != nil {\n\t\treturn false, err\n\t}\n\tdefer file.Close()\n\n\tbuf := make([]byte, 8)\n\tif _, err := io.ReadFull(file, buf); err != nil {\n\t\treturn false, err\n\t}\n\n\treturn bytes.Equal(buf, pngHeader), nil\n}\n\nfunc main() {\n\tpath := "image_test.png"\n\t_ = os.WriteFile(path, append(pngHeader, []byte("IHDR_CHUNK_DATA")...), 0644)\n\n\tvalid, err := isPNG(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Файл %s является валидным PNG: %v\\n", path, valid)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Файл image_test.png является валидным PNG: true'}], 'under_the_hood': 'Символы `\\r\\n\\x1a\\n` в сигнатуре PNG специально предназначены для обнаружения повреждений при ошибочной передаче файла в текстовом режиме FTP/DOS.', 'pitfalls': 'Используйте `io.ReadFull`, а не `file.Read`, чтобы гарантированно прочитать все 8 байт.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужна io.ReadFull вместо file.Read?»\n**Ответ:** `file.Read` может вернуть меньше запрошенного числа байт. `io.ReadFull` гарантирует точное чтение всего переданного среза или возвращает ошибку `io.ErrUnexpectedEOF`.'}, {'num': 68, 'title': 'Рекурсивное создание и удаление директорий: os.MkdirAll и os.RemoveAll', 'task': 'Создайте вложенную структуру папок с помощью `os.MkdirAll` и удалите её рекурсивно с помощью `os.RemoveAll`.', 'theory': '`os.MkdirAll` создает дерево каталогов. `os.RemoveAll(path)` рекурсивно удаляет весь каталог со всеми подпапками и файлами внутри (аналог команды `rm -rf`).', 'step_by_step': '1. Создадим дерево `sandbox/a/b/c`.\n2. Запишем файл внутри `sandbox/a/b/c/data.txt`.\n3. Проверим существование.\n4. Вызовем `os.RemoveAll("sandbox")`.\n5. Убедимся в полной очистке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tdeepPath := "sandbox/a/b/c"\n\n\t// 1. Создание дерева\n\tif err := os.MkdirAll(deepPath, 0755); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\t_ = os.WriteFile(deepPath+"/data.txt", []byte("Temporary build artifact"), 0644)\n\tfmt.Printf("Создано дерево каталогов: %s/\\n", deepPath)\n\n\t// 2. Рекурсивное удаление (rm -rf)\n\tif err := os.RemoveAll("sandbox"); err != nil {\n\t\tlog.Fatalf("Ошибка RemoveAll: %v", err)\n\t}\n\tfmt.Println("Вся структура \'sandbox/\' успешно и безопасно удалена")\n\n\t// 3. Проверка\n\t_, err := os.Stat("sandbox")\n\tfmt.Printf("Директория существует: %v\\n", err == nil)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# Создано дерево каталогов: sandbox/a/b/c/\n# Вся структура 'sandbox/' успешно и безопасно удалена\n# Директория существует: false"}], 'under_the_hood': '`os.RemoveAll` обходит директорию снизу вверх (post-order traversal), удаляя файлы системным вызовом `unlink` и папки вызовом `rmdir`.', 'pitfalls': 'Будьте предельно осторожны с `os.RemoveAll`: если путь окажется пустым `""` или `"/"`, можно случайно удалить корневую файловую систему!', 'bigtech_interview': '**Вопрос с собеседования:** «Что вернет os.RemoveAll, если переданного пути не существует?»\n**Ответ:** `os.RemoveAll` вернет `nil` (без ошибки), так как его контракт гарантирует, что после вызова путь гарантированно отсутствует на диске.'}, {'num': 69, 'title': 'Создание исполняемого Bash скрипта и установка прав 0755 через os.Chmod', 'task': '**Права доступа (Chmod)**: Создай скрипт (например, файл `script.sh` с текстом `echo "hello"`). Используй `os.Chmod`, чтобы выдать ему права на исполнение (`0755`).', 'theory': 'Для запуска скрипта в Unix файлу необходим бит `x` (Execution). Права `0755` (`rwxr-xr-x`) разрешают запуск скрипта всем пользователям системы.', 'step_by_step': '1. Создадим файл `script.sh` со строкой `#!/bin/bash\\necho "Hello from Go generated script!"\\n`.\n2. Изменим права на `0755` через `os.Chmod`.\n3. Запросим метаданные через `os.Stat` и выведем `info.Mode().Perm()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tscriptPath := "runner.sh"\n\tscriptBody := "#!/bin/sh\\necho \'Worker initialized successfully\'\\n"\n\n\t// 1. Создаем файл скрипта\n\tif err := os.WriteFile(scriptPath, []byte(scriptBody), 0644); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\t// 2. Делаем файл исполняемым (chmod 0755)\n\tif err := os.Chmod(scriptPath, 0755); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tinfo, err := os.Stat(scriptPath)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Файл:  %s\\n", scriptPath)\n\tfmt.Printf("Права: %v (%04o)\\n", info.Mode().Perm(), info.Mode().Perm())\n\tfmt.Printf("Исполняемый (x-бит установлен): %v\\n", info.Mode().Perm()&0111 != 0)\n\n\t_ = os.Remove(scriptPath)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Файл:  runner.sh\n# Права: -rwxr-xr-x (0755)\n# Исполняемый (x-бит установлен): true'}], 'under_the_hood': '`os.Chmod` устанавливает биты `0100` (User X), `0010` (Group X), `0001` (Other X).', 'pitfalls': 'В Windows бит исполнения определяется расширением файла (`.exe`, `.bat`), а не правами chmod.', 'bigtech_interview': '**Вопрос с собеседования:** «Как запустить сгенерированный скрипт напрямую из Go процесса?»\n**Ответ:** Использовать пакет `os/exec`: `cmd := exec.Command("./runner.sh"); out, err := cmd.CombinedOutput()`.'}, {'num': 70, 'title': 'Стриминговая бинарная сериализация среза int32 в LittleEndian', 'task': 'Напиши программу, которая записывает слайс `[]int32` в бинарный файл. Используй `encoding/binary.Write` с порядком байт `binary.LittleEndian`. Прочитай обратно и проверь.', 'theory': '`binary.Write(w, binary.LittleEndian, slice)` записывает весь срез целиком за один системный вызов, сохраняя по 4 байта на каждый элемент.', 'step_by_step': '1. Создадим срез `values := []int32{42, 1024, -999, 1337}`.\n2. Откроем файл `int32_data.bin` на запись.\n3. Вызовем `binary.Write`.\n4. Откроем на чтение и вычитаем срез через `binary.Read`.\n5. В `main` убедимся в совпадении данных.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/binary"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tfilename := "int32_data.bin"\n\toriginal := []int32{42, 1024, -999, 1337, 987654}\n\n\t// 1. Запись в бинарный файл\n\tfOut, err := os.Create(filename)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tif err := binary.Write(fOut, binary.LittleEndian, original); err != nil {\n\t\tfOut.Close()\n\t\tlog.Fatal(err)\n\t}\n\tfOut.Close()\n\n\t// 2. Чтение из бинарного файла\n\tfIn, err := os.Open(filename)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer fIn.Close()\n\n\trestored := make([]int32, len(original))\n\tif err := binary.Read(fIn, binary.LittleEndian, &restored); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Исходный массив:      %v\\n", original)\n\tfmt.Printf("Прочитанный массив:   %v\\n", restored)\n\n\t_ = os.Remove(filename)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Исходный массив:      [42 1024 -999 1337 987654]\n# Прочитанный массив:   [42 1024 -999 1337 987654]'}], 'under_the_hood': '`binary.Write` вычисляет размер среза через `reflect` и копирует память напрямую в дескриптор.', 'pitfalls': 'Длина среза `restored` должна быть заранее инициализирована нужным количеством элементов `make([]int32, N)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как прочитать бинарный файл, если количество int32 чисел заранее неизвестно?»\n**Ответ:** Узнать размер файла через `stat.Size()`, вычислить количество элементов `count := stat.Size() / 4` и аллоцировать срез `make([]int32, count)`.'}, {'num': 71, 'title': 'Разбиение большого бинарного файла на чанки (Split) и сборка обратно (Merge)', 'task': "Напиши программу, которая разбивает большой бинарный файл на части (chunk'и) заданного размера (например, 1MB каждый). Затем напиши программу-сборщик, которая объединяет chunk'и обратно.", 'theory': 'Паттерн Chunking (нарезка на части) применяется в протоколах BitTorrent, S3 Multipart Upload и Telegram Bot API для надежной передачи больших файлов по нестабильной сети.', 'step_by_step': '1. Создадим тестовый файл `large_payload.dat`.\n2. Реализуем функцию `SplitFile(path string, chunkSize int64) ([]string, error)`.\n3. Реализуем функцию `MergeChunks(chunks []string, dst string) error`.\n4. В `main` сверим размер и содержимое оригинала и собранного файла.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc SplitFile(srcPath string, chunkSize int64) ([]string, error) {\n\tsrc, err := os.Open(srcPath)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tdefer src.Close()\n\n\tvar chunkFiles []string\n\tpart := 1\n\n\tfor {\n\t\tchunkName := fmt.Sprintf("%s.part%03d", srcPath, part)\n\t\tdst, err := os.Create(chunkName)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\n\t\t// Копируем ровно chunkSize байт\n\t\tn, err := io.CopyN(dst, src, chunkSize)\n\t\tdst.Close()\n\n\t\tif n > 0 {\n\t\t\tchunkFiles = append(chunkFiles, chunkName)\n\t\t\tpart++\n\t\t}\n\t\tif err == io.EOF {\n\t\t\tbreak\n\t\t}\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t}\n\treturn chunkFiles, nil\n}\n\nfunc MergeChunks(chunks []string, dstPath string) error {\n\tdst, err := os.Create(dstPath)\n\tif err != nil {\n\t\treturn err\n\t}\n\tdefer dst.Close()\n\n\tfor _, chunk := range chunks {\n\t\tin, err := os.Open(chunk)\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\t_, err = io.Copy(dst, in)\n\t\tin.Close()\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t}\n\treturn nil\n}\n\nfunc main() {\n\toriginalData := []byte("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ_PAYLOAD_DATA")\n\t_ = os.WriteFile("source.dat", originalData, 0644)\n\n\t// Нарезка чанками по 16 байт\n\tchunks, err := SplitFile("source.dat", 16)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tfmt.Printf("Файл нарезан на %d чанков: %v\\n", len(chunks), chunks)\n\n\t// Сборка обратно\n\tif err := MergeChunks(chunks, "restored.dat"); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\trestoredData, _ := os.ReadFile("restored.dat")\n\tfmt.Printf("Целостность сборки: %v\\n", bytes.Equal(originalData, restoredData))\n\n\t// Очистка\n\t_ = os.Remove("source.dat")\n\t_ = os.Remove("restored.dat")\n\tfor _, c := range chunks {\n\t\t_ = os.Remove(c)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Файл нарезан на 4 чанков: [source.dat.part001 source.dat.part002 source.dat.part003 source.dat.part004]\n# Целостность сборки: true'}], 'under_the_hood': '`io.CopyN(dst, src, n)` оборачивает источник в `io.LimitReader` и выполняет потоковое копирование ровно $N$ байт.', 'pitfalls': 'Не забывайте закрывать дескрипторы каждого чанка перед открытием следующего.', 'bigtech_interview': '**Вопрос с собеседования:** «Как работает S3 Multipart Upload?»\n**Ответ:** Клиент разбивает файл на части $\\ge 5$MB, параллельно загружает каждый чанк через `UploadPart` горутинами, и завершает вызовом `CompleteMultipartUpload`, где AWS S3 атомарно объединяет части в один объект на стороне хранилища.'}, {'num': 72, 'title': 'Дозапись данных в существующий лог-файл через O_APPEND', 'task': '**Дозапись в файл (Append)**: Откройте существующий файл с помощью `os.OpenFile` с флагами `os.O_APPEND|os.O_WRONLY`. Допишите новую строку в конец файла, не стирая старое содержимое.', 'theory': 'Флаг `os.O_APPEND` перемещает файловый курсор на физический конец файла перед каждым системным вызовом записи.', 'step_by_step': '1. Создадим файл `messages.txt` с начальным текстом.\n2. Откроем через `os.OpenFile(path, os.O_APPEND|os.O_WRONLY, 0644)`.\n3. Допишем `"Second line of text\\n"`.\n4. В `main` выведем итоговый файл.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "messages.txt"\n\t_ = os.WriteFile(path, []byte("First line of text\\n"), 0644)\n\n\tf, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY, 0644)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer f.Close()\n\n\tif _, err := f.WriteString("Second line of text (appended)\\n"); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tdata, _ := os.ReadFile(path)\n\tfmt.Print(string(data))\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# First line of text\n# Second line of text (appended)'}], 'under_the_hood': 'Флаг `O_APPEND` поддерживается ядром операционной системы на уровне VFS (Virtual File System).', 'pitfalls': 'Флаг `O_APPEND` работает только на запись. Если требуется одновременно читать и дописывать, используйте `os.O_APPEND|os.O_RDWR`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в микросервисах логи пишут в stdout, а не дописывают в файл через O_APPEND?»\n**Ответ:** По методологии 12-Factor App микросервисы в Kubernetes направляют логи в `stdout`/`stderr`. Драйвер контейнеризации (containerd/cri-o) сам перенаправляет поток в лог-коллекторы (Vector, Fluentbit), избавляя приложение от управления файлами логов и ротацией.'}, {'num': 73, 'title': 'Файловая база данных с фиксированным размером записей (CRUD)', 'task': 'Напиши программу, которая реализует простую базу данных в файле: запись структур `Record { ID int; Name string; Score float64 }` с фиксированным размером записи. Реализуй CRUD: Create, Read, Update, Delete (soft delete).', 'theory': 'Файловые СУБД с фиксированным размером слота (Slot Size) позволяют вычислять точное смещение любой записи по формуле: $\\text{offset} = \\text{slotID} \\times \\text{recordSize}$. Чтение и перезапись выполняются за $O(1)$ через `file.Seek`.', 'step_by_step': '1. Объявим структуру `Record struct { ID int32; Name [24]byte; Score float64; IsDeleted bool }`.\n2. Реализуем `WriteRecord(slot int, r Record)` через `file.Seek`.\n3. Реализуем `ReadRecord(slot int)` через `file.Seek`.\n4. Реализуем `SoftDelete(slot int)` через обновление флага `IsDeleted`.\n5. В `main` покажем работу CRUD-операций.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/binary"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\ntype Record struct {\n\tID        int32\n\tName      [24]byte\n\tScore     float64\n\tIsDeleted bool\n}\n\nconst recordSize = 37 // 4 + 24 + 8 + 1 байт\n\ntype DatabaseEngine struct {\n\tfile *os.File\n}\n\nfunc NewDB(path string) (*DatabaseEngine, error) {\n\tf, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0644)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn &DatabaseEngine{file: f}, nil\n}\n\nfunc (db *DatabaseEngine) Close() error {\n\treturn db.file.Close()\n}\n\nfunc (db *DatabaseEngine) Write(slot int64, rec Record) error {\n\toffset := slot * recordSize\n\tif _, err := db.file.Seek(offset, ioSeekStart()); err != nil {\n\t\treturn err\n\t}\n\treturn binary.Write(db.file, binary.LittleEndian, rec)\n}\n\nfunc (db *DatabaseEngine) Read(slot int64) (Record, error) {\n\toffset := slot * recordSize\n\tvar rec Record\n\tif _, err := db.file.Seek(offset, ioSeekStart()); err != nil {\n\t\treturn rec, err\n\t}\n\terr := binary.Read(db.file, binary.LittleEndian, &rec)\n\treturn rec, err\n}\n\nfunc ioSeekStart() int { return 0 }\n\nfunc main() {\n\tdbPath := "mini_engine.db"\n\tdb, err := NewDB(dbPath)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer func() {\n\t\tdb.Close()\n\t\t_ = os.Remove(dbPath)\n\t}()\n\n\t// 1. Create: пишем в слот 0 и 1\n\tvar name1 [24]byte\n\tcopy(name1[:], "Alice")\n\t_ = db.Write(0, Record{ID: 101, Name: name1, Score: 98.5, IsDeleted: false})\n\n\tvar name2 [24]byte\n\tcopy(name2[:], "Bob")\n\t_ = db.Write(1, Record{ID: 102, Name: name2, Score: 85.0, IsDeleted: false})\n\n\t// 2. Read: прямое чтение слота 1 за O(1)\n\trec, _ := db.Read(1)\n\tcleanName := string(bytes.TrimRight(rec.Name[:], "\\x00"))\n\tfmt.Printf("[Read Slot 1] ID=%d, Name=%s, Score=%.1f\\n", rec.ID, cleanName, rec.Score)\n\n\t// 3. Delete (Soft delete) слота 0:\n\trec0, _ := db.Read(0)\n\trec0.IsDeleted = true\n\t_ = db.Write(0, rec0)\n\n\trec0Updated, _ := db.Read(0)\n\tfmt.Printf("[Read Slot 0] Deleted: %v\\n", rec0Updated.IsDeleted)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Read Slot 1] ID=102, Name=Bob, Score=85.0\n# [Read Slot 0] Deleted: true'}], 'under_the_hood': '`file.Seek(slot * recordSize, io.SeekStart)` мгновенно смещает курсор в точную ячейку на диске без сканирования предыдущих записей.', 'pitfalls': 'Используйте строгие массивы `[24]byte` вместо срезов `[]byte`, иначе размер структуры будет варьироваться и сломает расчет смещения.', 'bigtech_interview': '**Вопрос с собеседования:** «Как устроены файлы страниц в PostgreSQL / InnoDB?»\n**Ответ:** Таблицы хранятся в виде страниц фиксированного размера (обычно 8KB или 16KB). В начале страницы находится заголовок (Page Header), а строки адресуются через массив смещений (Slot Array) в конце страницы.'}, {'num': 74, 'title': 'Блочное чтение через bufio.NewReader порциями по 1024 байта', 'task': 'Используй `bufio.NewReader` для чтения файла блоками по 1024 байта (через метод `Read`).', 'theory': '`bufio.NewReader(f)` буферизует чтение из диска, объединяя системные вызовы ядра и предоставляя удобный метод `r.Read(buf)`.', 'step_by_step': '1. Создадим тестовый файл `dataset.bin`.\n2. Обернем `os.Open` в `bufio.NewReader`.\n3. В цикле прочитаем блоками по 1024 байта.\n4. Проверим `io.EOF`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"errors"\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "dataset.bin"\n\t_ = os.WriteFile(path, make([]byte, 2500), 0644) // 2500 байт\n\n\tfile, err := os.Open(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer file.Close()\n\n\treader := bufio.NewReader(file)\n\tbuf := make([]byte, 1024)\n\ttotalRead := 0\n\tchunkNum := 1\n\n\tfor {\n\t\tn, err := reader.Read(buf)\n\t\tif n > 0 {\n\t\t\tfmt.Printf("Чанк #%d: прочитано %d байт\\n", chunkNum, n)\n\t\t\ttotalRead += n\n\t\t\tchunkNum++\n\t\t}\n\t\tif err != nil {\n\t\t\tif errors.Is(err, io.EOF) {\n\t\t\t\tbreak\n\t\t\t}\n\t\t\tlog.Fatal(err)\n\t\t}\n\t}\n\n\tfmt.Printf("Всего прочитано: %d байт\\n", totalRead)\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Чанк #1: прочитано 1024 байт\n# Чанк #2: прочитано 1024 байт\n# Чанк #3: прочитано 452 байт\n# Всего прочитано: 2500 байт'}], 'under_the_hood': '`bufio.Reader` держит свой внутренний буфер 4096 байт и считывает данные из ОС крупными блоками.', 'pitfalls': 'Метод `reader.Read(buf)` может вернуть $n < len(buf)$ даже если файл еще не закончился.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда bufio.Reader читает напрямую в пользовательский буфер минуя внутренний кэш?»\n**Ответ:** Если размер запрашиваемого буфера `len(buf)` больше или равен размеру внутреннего буфера `bufio.Reader` (по умолчанию 4KB), ридер оптимизирует системный вызов и читает напрямую в целевой слайс.'}, {'num': 75, 'title': 'Реализация утилиты tail: чтение последних N байт через Seek(offset, io.SeekEnd)', 'task': 'Напиши программу, которая читает файл с произвольной позиции (`os.File.Seek`). Реализуй "tail" — чтение последних N байт файла без загрузки всего файла в память.', 'theory': 'Утилита `tail` считывает последние байты лог-файла. Перемещение `file.Seek(-N, io.SeekEnd)` мгновенно ставит указатель чтения в конец файла за время $O(1)$ без чтения предыдущих терабайт.', 'step_by_step': '1. Создадим большой файл лога.\n2. Реализуем функцию `TailBytes(path string, n int64) ([]byte, error)`.\n3. Запросим размер файла через `file.Stat()`.\n4. Сместимся на `-n` от `io.SeekEnd`.\n5. Вычитаем остаток файла и распечатаем.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc TailBytes(path string, n int64) ([]byte, error) {\n\tfile, err := os.Open(path)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tdefer file.Close()\n\n\tinfo, err := file.Stat()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\n\tsize := info.Size()\n\toffset := int64(0)\n\tif size > n {\n\t\toffset = -n\n\t} else {\n\t\toffset = -size\n\t}\n\n\t// Смещение назад от конца файла\n\tif _, err := file.Seek(offset, io.SeekEnd); err != nil {\n\t\treturn nil, err\n\t}\n\n\treturn io.ReadAll(file)\n}\n\nfunc main() {\n\tpath := "big_server.log"\n\tpayload := "2026-09-02 12:00:00 Old Log Event\\n2026-09-02 18:30:00 CRITICAL_PAYMENT_FAILURE_RETRY"\n\t_ = os.WriteFile(path, []byte(payload), 0644)\n\n\ttail, err := TailBytes(path, 40)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Println("--- Последние байты файла (tail) ---")\n\tfmt.Printf("%s\\n", string(tail))\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Последние байты файла (tail) ---\n# 00 CRITICAL_PAYMENT_FAILURE_RETRY'}], 'under_the_hood': '`file.Seek(-n, io.SeekEnd)` передает отрицательное смещение в системный вызов `lseek(fd, -n, SEEK_END)` ядра Linux.', 'pitfalls': 'Если размер файла меньше $N$, смещение `-n` вернет ошибку `EINVAL: invalid argument`. Всегда проверяйте `size > n`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать tail -f (слежение за файлом в реальном времени)?»\n**Ответ:** Открыть файл, сделать `Seek(0, io.SeekEnd)`. В цикле читать `file.Read(buf)`. Если вернулся `io.EOF`, делать паузу `time.Sleep(100ms)` или слушать события файловой системы ядра через Linux `inotify` (пакет `fsnotify`).'}, {'num': 76, 'title': 'Прямая перекачка данных между файловыми дескрипторами через io.Copy', 'task': '**Копирование файлов**: Напиши программу, которая открывает `source.txt`, создает `dest.txt` и использует `io.Copy` для перекачки данных напрямую между файловыми дескрипторами.', 'theory': '`io.Copy` связывает `io.Reader` и `io.Writer`. Для двух файлов `os.File` в Linux ядро использует `copy_file_range(2)` без копирования страниц памяти в адресное пространство процесса.', 'step_by_step': '1. Создадим `source.txt`.\n2. Откроем `source.txt` на чтение.\n3. Создадим `dest.txt` на запись.\n4. Вызовем `io.Copy(dest, source)`.\n5. В `main` убедимся в успешном копировании.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc directCopy(srcName, dstName string) (int64, error) {\n\tsrc, err := os.Open(srcName)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tdefer src.Close()\n\n\tdst, err := os.Create(dstName)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tdefer dst.Close()\n\n\treturn io.Copy(dst, src)\n}\n\nfunc main() {\n\t_ = os.WriteFile("source.txt", []byte("Direct Kernel Descriptor Transfer"), 0644)\n\n\tn, err := directCopy("source.txt", "dest.txt")\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Успешно перекачано %d байт напрямую через дескрипторы\\n", n)\n\n\t_ = os.Remove("source.txt")\n\t_ = os.Remove("dest.txt")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Успешно перекачано 33 байт напрямую через дескрипторы'}], 'under_the_hood': '`io.Copy` не выделяет память в куче при каждом вызове, а переиспользует буферы рантайма.', 'pitfalls': 'Если `dest.txt` уже существовал, `os.Create` перезапишет его.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова скорость io.Copy при копировании файла внутри одной файловой системы Linux?»\n**Ответ:** Благодаря `copy_file_range` ядро выполняет клонирование экстентов (Reflink / CoW в Btrfs/XFS/ZFS) практически мгновенно со скоростью в десятки гигабайт в секунду без реального чтения и записи блоков.'}, {'num': 77, 'title': 'Пословное сканирование текста через bufio.Scanner и bufio.ScanWords', 'task': '**Посимвольное или пословное чтение**: Используя `bufio.Scanner` и метод `scanner.Split(bufio.ScanWords)`, настройте сканер так, чтобы он читал файл не построчно, а слово за словом. Выведите каждое слово на новой строке.', 'theory': '`scanner.Split(bufio.ScanWords)` переключает сканер в режим извлечения отдельных слов, автоматически пропуская любые пробельные символы (пробелы, табуляции, переводы строк).', 'step_by_step': '1. Создадим файл `words.txt`.\n2. Откроем файл через `os.Open`.\n3. Настроим `scanner.Split(bufio.ScanWords)`.\n4. В цикле `for scanner.Scan()` выведем каждое слово.\n5. Проверим `scanner.Err()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "words.txt"\n\t_ = os.WriteFile(path, []byte("HighLoad   Golang \\n Architecture \\t Distributed\\nSystems"), 0644)\n\n\tfile, err := os.Open(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer file.Close()\n\n\tscanner := bufio.NewScanner(file)\n\tscanner.Split(bufio.ScanWords) // Настройка пословного режима\n\n\twordIdx := 1\n\tfor scanner.Scan() {\n\t\tfmt.Printf("Слово #%d: %s\\n", wordIdx, scanner.Text())\n\t\twordIdx++\n\t}\n\n\tif err := scanner.Err(); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Слово #1: HighLoad\n# Слово #2: Golang\n# Слово #3: Architecture\n# Слово #4: Distributed\n# Слово #5: Systems'}], 'under_the_hood': '`bufio.ScanWords` использует функцию `unicode.IsSpace(r)` для пропуска последовательностей пробелов.', 'pitfalls': 'Знаки препинания (запятые, точки) не удаляются автоматически и остаются частью слова (например, `"word,"`).', 'bigtech_interview': '**Вопрос с собеседования:** «Как построить частотный словарь слов (Word Count Map) из 10GB текста на Go?»\n**Ответ:** Читать файл потоково через `bufio.Scanner` с `bufio.ScanWords` и инкрементировать счетчик в `map[string]int` (или использовать `scanner.Bytes()` с кастомным хеш-мапом без аллокаций).'}, {'num': 78, 'title': 'Мониторинг изменений файла по размеру и времени модификации (Polling)', 'task': 'Напиши программу, которая мониторит файл на изменения (размер, время модификации). Используй `os.Stat` в цикле с `time.Sleep`. При изменении — выведи сообщение.', 'theory': 'Опрос метаданных (Polling File Watcher) через `os.Stat` — простейший кроссплатформенный способ отслеживания изменений файлов. Он сравнивает `info.ModTime()` и `info.Size()` между интервалами опроса.', 'step_by_step': '1. Создадим файл `config.live`.\n2. Запросим начальные метаданные `lastMod := info.ModTime()`.\n3. В цикле выполним 3 проверки с `time.Sleep`.\n4. Изменим файл во время работы цикла и зафиксируем событие.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n\t"time"\n)\n\nfunc main() {\n\tpath := "config.live"\n\t_ = os.WriteFile(path, []byte("v1"), 0644)\n\n\tinfo, err := os.Stat(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tlastMod := info.ModTime()\n\tlastSize := info.Size()\n\n\tfmt.Printf("Мониторинг файла %s запущен...\\n", path)\n\n\t// Имитация фонового изменения файла\n\tgo func() {\n\t\ttime.Sleep(20 * time.Millisecond)\n\t\t_ = os.WriteFile(path, []byte("v2_updated_configuration_payload"), 0644)\n\t}()\n\n\tfor i := 0; i < 4; i++ {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tcurrentInfo, err := os.Stat(path)\n\t\tif err != nil {\n\t\t\tcontinue\n\t\t}\n\n\t\tif currentInfo.ModTime() != lastMod || currentInfo.Size() != lastSize {\n\t\t\tfmt.Printf("[EVENT] Файл %s изменен! Новый размер: %d B, Время: %s\\n",\n\t\t\t\tpath, currentInfo.Size(), currentInfo.ModTime().Format("15:04:05.000"))\n\t\t\tlastMod = currentInfo.ModTime()\n\t\t\tlastSize = currentInfo.Size()\n\t\t}\n\t}\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Мониторинг файла config.live запущен...\n# [EVENT] Файл config.live изменен! Новый размер: 32 B, Время: 18:30:00.020'}], 'under_the_hood': '`os.Stat` выполняет системный вызов ядра `stat(2)`.', 'pitfalls': 'Polling создает постоянную нагрузку на CPU/диск при частых проверках. Для боевых приложений используют пакет `github.com/fsnotify/fsnotify`, работающий на Linux `inotify` / macOS `kqueue`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество inotify перед polling (os.Stat в цикле)?»\n**Ответ:** `inotify` работает на основе прерываний ядра ОС (Event-Driven). Процесс Go спит в epoll и пробуждается мгновенно только тогда, когда ядро фиксирует запись в файл, с 0% нагрузки на CPU в состоянии покоя.'}, {'num': 79, 'title': 'Рекурсивный расчет суммарного размера директории через filepath.WalkDir', 'task': 'Напишите утилиту, которая принимает путь к папке и выводит суммарный размер всех файлов внутри неё, рекурсивно обходя подпапки.', 'theory': '`filepath.WalkDir` обходит все вложенные элементы. Метод `d.Info()` запрашивает метаданные файла, из которых извлекается точный размер `info.Size()`.', 'step_by_step': '1. Создадим дерево каталогов с файлами разного размера.\n2. Реализуем функцию `CalculateDirSize(path string) (int64, int, error)`.\n3. Просуммируем `info.Size()` для всех файлов `!d.IsDir()`.\n4. В `main` выведем суммарный размер и количество файлов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io/fs"\n\t"log"\n\t"os"\n\t"path/filepath"\n)\n\nfunc CalculateDirSize(root string) (totalSize int64, fileCount int, err error) {\n\terr = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif !d.IsDir() {\n\t\t\tinfo, err := d.Info()\n\t\t\tif err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t\ttotalSize += info.Size()\n\t\t\tfileCount++\n\t\t}\n\t\treturn nil\n\t})\n\treturn totalSize, fileCount, err\n}\n\nfunc main() {\n\troot := "metrics_storage"\n\t_ = os.MkdirAll(root+"/node1/logs", 0755)\n\t_ = os.WriteFile(root+"/node1/logs/app.log", make([]byte, 1024), 0644) // 1024 B\n\t_ = os.WriteFile(root+"/summary.json", make([]byte, 512), 0644)        // 512 B\n\n\tsize, count, err := CalculateDirSize(root)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Директория:       %s\\n", root)\n\tfmt.Printf("Всего файлов:     %d\\n", count)\n\tfmt.Printf("Суммарный размер: %d байт (%.2f KB)\\n", size, float64(size)/1024)\n\n\t_ = os.RemoveAll(root)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Директория:       metrics_storage\n# Всего файлов:     2\n# Суммарный размер: 1536 байт (1.50 KB)'}], 'under_the_hood': '`d.Info()` вызывает `stat` только для файлов, экономя системные вызовы для каталогов.', 'pitfalls': 'Учитывайте, что размер файлов на диске (Disk Usage) кратен размеру кластера файловой системы (обычно 4096 байт), поэтому 1-байтный файл занимает на диске 4KB.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Apparent Size от Disk Usage (du)?»\n**Ответ:** Apparent Size (`info.Size()`) — логический размер данных в байтах. Disk Usage — физический объем секторов на диске с учетом размера блоков и разреженных файлов (Sparse Files).'}, {'num': 80, 'title': 'Инспекция каталога через os.ReadDir: фильтрация файлов и подпапок', 'task': '**Работа с папками**: Используй `os.ReadDir`, чтобы получить список всех файлов и папок в текущей директории. Выведи их имена и укажи, кто из них является директорией (метод `IsDir()`).', 'theory': '`os.ReadDir(path)` возвращает срез `[]fs.DirEntry`. Метод `entry.IsDir()` возвращает булевый флаг, позволяя разделить папки и обычные файлы без вызова `stat`.', 'step_by_step': '1. Создадим папку `explorer_demo`.\n2. Добавим файлы и подпапки.\n3. Прочитаем записи через `os.ReadDir`.\n4. Выведем форматированный список с типами `[DIR]` и `[FILE]`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "explorer_demo"\n\t_ = os.MkdirAll(path+"/subfolder", 0755)\n\t_ = os.WriteFile(path+"/data.csv", []byte("1,2,3"), 0644)\n\t_ = os.WriteFile(path+"/server.go", []byte("package main"), 0644)\n\n\tentries, err := os.ReadDir(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Каталог: %s/\\n", path)\n\tfor _, e := range entries {\n\t\ttypeStr := "[FILE]"\n\t\tif e.IsDir() {\n\t\t\ttypeStr = "[DIR ]"\n\t\t}\n\t\tfmt.Printf("%s %s\\n", typeStr, e.Name())\n\t}\n\n\t_ = os.RemoveAll(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Каталог: explorer_demo/\n# [FILE] data.csv\n# [FILE] server.go\n# [DIR ] subfolder'}], 'under_the_hood': 'Свойство `entry.IsDir()` вычисляется из `d_type` системного вызова `getdents64`.', 'pitfalls': '`os.ReadDir` сортирует результаты лексикографически по имени файла.', 'bigtech_interview': '**Вопрос с собеседования:** «Как определить, что DirEntry является симлинком?»\n**Ответ:** Проверить битовую маску: `if e.Type()&fs.ModeSymlink != 0 { /* элемент является символической ссылкой */ }`.'}, {'num': 81, 'title': 'Сериализация среза структур в бинарный файл через encoding/gob', 'task': 'Создайте структуру `Record` и запишите слайс таких структур в бинарный файл с помощью пакета `encoding/gob`.', 'theory': '`encoding/gob` поддерживает прямую сериализацию срезов структур `[]Record` без необходимости кодировать каждый элемент вручную.', 'step_by_step': '1. Объявим структуру `Record struct { ID int; Task string; Done bool }`.\n2. Создадим срез записей `records`.\n3. Сериализуем через `gob.NewEncoder(f).Encode(records)`.\n4. Откроем файл и восстановим весь срез через `gob.NewDecoder(f).Decode(&restored)`.\n5. В `main` распечатаем результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/gob"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\ntype TaskRecord struct {\n\tID        int\n\tTaskTitle string\n\tIsDone    bool\n}\n\nfunc main() {\n\tpath := "tasks.gob"\n\toriginal := []TaskRecord{\n\t\t{ID: 1, TaskTitle: "Design Database Schema", IsDone: true},\n\t\t{ID: 2, TaskTitle: "Implement JWT Middleware", IsDone: true},\n\t\t{ID: 3, TaskTitle: "Setup Kubernetes Cluster", IsDone: false},\n\t}\n\n\t// 1. Запись среза структур в gob\n\toutFile, err := os.Create(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tif err := gob.NewEncoder(outFile).Encode(original); err != nil {\n\t\toutFile.Close()\n\t\tlog.Fatal(err)\n\t}\n\toutFile.Close()\n\n\t// 2. Чтение среза структур\n\tinFile, err := os.Open(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer inFile.Close()\n\n\tvar restored []TaskRecord\n\tif err := gob.NewDecoder(inFile).Decode(&restored); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Println("Восстановленный список задач из gob:")\n\tfor _, t := range restored {\n\t\tfmt.Printf(" -> [%02d] (Done: %-5v) %s\\n", t.ID, t.IsDone, t.TaskTitle)\n\t}\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Восстановленный список задач из gob:\n#  -> [01] (Done: true ) Design Database Schema\n#  -> [02] (Done: true ) Implement JWT Middleware\n#  -> [03] (Done: false) Setup Kubernetes Cluster'}], 'under_the_hood': '`gob.Encode` записывает длину среза в заголовок и сериализует элементы последовательно.', 'pitfalls': 'Если типы полей изменились между версиями программы, `gob.Decode` может вернуть ошибку несовместимости типов.', 'bigtech_interview': '**Вопрос с собеседования:** «Нужно ли регистрировать типы через gob.Register?»\n**Ответ:** Только при сериализации интерфейсов (например, когда поле структуры имеет тип `interface{}` или `any`), чтобы декодер знал конкретный тип за интерфейсом.'}, {'num': 82, 'title': 'Определение размера файла через file.Stat().Size() перед чтением', 'task': 'Узнай размер файла с помощью `file.Stat().Size()` до его чтения.', 'theory': 'Вызов `file.Stat()` на уже открытом дескрипторе использует быстрый системный вызов `fstat(2)`, что позволяет предвыделить буфер памяти точной длины `make([]byte, size)`.', 'step_by_step': '1. Создадим файл `payload.bin`.\n2. Откроем файл через `os.Open`.\n3. Запросим `info, err := file.Stat()`.\n4. Получим точный размер `info.Size()`.\n5. Выделим буфер и прочитаем файл через `io.ReadFull`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "payload.bin"\n\t_ = os.WriteFile(path, []byte("Exact Buffer Size Allocation"), 0644)\n\n\tfile, err := os.Open(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer file.Close()\n\n\t// Получение размера до чтения\n\tinfo, err := file.Stat()\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfileSize := info.Size()\n\tfmt.Printf("Размер файла до чтения: %d байт\\n", fileSize)\n\n\t// Выделение точного буфера (0 лишних байт):\n\tbuf := make([]byte, fileSize)\n\tn, err := io.ReadFull(file, buf)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Успешно вычитано ровно %d байт: %s\\n", n, string(buf))\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Размер файла до чтения: 28 байт\n# Успешно вычитано ровно 28 байт: Exact Buffer Size Allocation'}], 'under_the_hood': '`fstat(2)` обращается к дескриптору в памяти ядра без повторного поиска пути в каталоге диска.', 'pitfalls': 'В псевдофайловых системах Linux (`/proc/cpuinfo`, `/sys/`) размер всегда возвращается равным `0`, хотя данные внутри есть.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему stat /proc/version возвращает Size=0?»\n**Ответ:** Файлы в `/proc` и `/sys` не существуют на диске — их содержимое генерируется ядром динамически на лету в момент вызова `read(2)`.'}, {'num': 83, 'title': 'Буферизованная запись 10 000 строк и обязательность Flush()', 'task': '**Буферизованная запись (Writer)**: Напишите программу, которая записывает 10 000 строк в файл. Используйте `bufio.NewWriter`. Не забудьте вызвать метод `Flush()` в конце (объясните в комментариях, почему без `Flush` часть данных может не записаться).', 'theory': '`bufio.NewWriter` накапливает строки во внутреннем буфере в RAM. Если функция завершится без вызова `writer.Flush()`, последняя накопленная порция данных (до 4096 байт) будет утеряна при закрытии дескриптора.', 'step_by_step': '1. Создадим файл `benchmark.log`.\n2. Обернем его в `bufio.NewWriter`.\n3. В цикле запишем 10 000 строк.\n4. Вызовем `writer.Flush()`.\n5. Проверим количество строк в полученном файле.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "benchmark.log"\n\tfile, err := os.Create(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer file.Close()\n\n\twriter := bufio.NewWriter(file)\n\n\tconst totalLines = 10000\n\tfor i := 1; i <= totalLines; i++ {\n\t\tline := fmt.Sprintf("EventID=%05d Status=SUCCESS Latency=0.45ms\\n", i)\n\t\tif _, err := writer.WriteString(line); err != nil {\n\t\t\tlog.Fatal(err)\n\t\t}\n\t}\n\n\t// ОБЯЗАТЕЛЬНО: сброс остатка внутреннего буфера в дескриптор файла\n\t// Без Flush() хвост буфера (до 4KB) останется в памяти и не попадет на диск.\n\tif err := writer.Flush(); err != nil {\n\t\tlog.Fatalf("Ошибка Flush: %v", err)\n\t}\n\n\tinfo, _ := file.Stat()\n\tfmt.Printf("Успешно записано %d строк через bufio.Writer. Размер: %d байт\\n", totalLines, info.Size())\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Успешно записано 10000 строк через bufio.Writer. Размер: 420000 байт'}], 'under_the_hood': '`bufio.Writer` сбрасывает данные на диск только при заполнении буфера (порог 4096 байт) или при явном `Flush()`.', 'pitfalls': 'Идиоматичный паттерн: объявлять `defer writer.Flush()` сразу после создания `bufio.Writer`.', 'bigtech_interview': '**Вопрос с собеседования:** «Гарантирует ли Flush() сохранение данных на физическом носителе при отключении питания?»\n**Ответ:** Нет! `writer.Flush()` сбрасывает данные из Go-буфера в Page Cache ядра Linux. Для гарантии физической записи на магнитные пластины/ячейки NAND SSD необходимо вызвать `file.Sync()` (системный вызов `fsync`).'}, {'num': 84, 'title': 'Реализация паттерна ротации лог-файлов по размеру', 'task': 'Напиши программу, которая реализует лог-файл с ротацией: при достижении размера 1MB — переименовывает текущий файл в `log.1`, `log.2` и т.д., и создаёт новый.', 'theory': 'Ротация логов предотвращает переполнение диска. При превышении лимита размера текущий файл атомарно переименовывается (`os.Rename`), а для записи открывается новый чистый дескриптор.', 'step_by_step': '1. Реализуем структуру `RotatingLogger`.\n2. В методе `Write(msg string)` проверяем текущий размер через `file.Stat()`.\n3. Если `size >= maxSize` — вызываем `rotate()`.\n4. В `main` запишем данные и проверим ротацию.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\ntype RotatingLogger struct {\n\tbasePath string\n\tmaxBytes int64\n\tfile     *os.File\n\tcount    int\n}\n\nfunc NewRotatingLogger(basePath string, maxBytes int64) (*RotatingLogger, error) {\n\tf, err := os.OpenFile(basePath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn &RotatingLogger{basePath: basePath, maxBytes: maxBytes, file: f}, nil\n}\n\nfunc (l *RotatingLogger) rotate() error {\n\tl.file.Close()\n\tl.count++\n\tbackupPath := fmt.Sprintf("%s.%d", l.basePath, l.count)\n\n\tif err := os.Rename(l.basePath, backupPath); err != nil {\n\t\treturn err\n\t}\n\n\tfmt.Printf("[ROTATION] Файл ротирован в %s\\n", backupPath)\n\n\tf, err := os.OpenFile(l.basePath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)\n\tif err != nil {\n\t\treturn err\n\t}\n\tl.file = f\n\treturn nil\n}\n\nfunc (l *RotatingLogger) Log(msg string) error {\n\tinfo, err := l.file.Stat()\n\tif err != nil {\n\t\treturn err\n\t}\n\tif info.Size() >= l.maxBytes {\n\t\tif err := l.rotate(); err != nil {\n\t\t\treturn err\n\t\t}\n\t}\n\t_, err = l.file.WriteString(msg + "\\n")\n\treturn err\n}\n\nfunc (l *RotatingLogger) Close() error {\n\treturn l.file.Close()\n}\n\nfunc main() {\n\tbase := "app_rot.log"\n\t// Лимит 40 байт для демонстрации\n\tlogger, err := NewRotatingLogger(base, 40)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer logger.Close()\n\n\t_ = logger.Log("Line 1: Server initialized")\n\t_ = logger.Log("Line 2: Heavy database query completed")\n\t_ = logger.Log("Line 3: Cache cleared")\n\n\t// Очистка\n\t_ = os.Remove(base)\n\t_ = os.Remove(base + ".1")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [ROTATION] Файл ротирован в app_rot.log.1'}], 'under_the_hood': '`os.Rename` в пределах одной файловой системы атомарен и выполняется за $O(1)$ без копирования байтов.', 'pitfalls': 'В production-коде для ротации логов используют проверенный пакет `gopkg.in/natefinch/lumberjack.v2`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему os.Rename атомарен в Linux?»\n**Ответ:** Системный вызов `renameat2` просто обновляет запись указателя на `inode` в каталоге родительской директории без перемещения самих блоков данных на физическом носителе.'}, {'num': 85, 'title': 'Модификация середины файла в режиме os.O_RDWR без перезаписи', 'task': '**[Каверзный кейс]**: Открой файл для чтения и записи одновременно `os.O_RDWR`. Запиши что-то в середину файла, не затирая его полностью (используй `Seek`).', 'theory': 'Режим `os.O_RDWR` позволяет одновременно читать и записывать в произвольные участки файла через перемещение курсора `file.Seek`.', 'step_by_step': '1. Создадим файл `[1234567890]`.\n2. Откроем в режиме `os.O_RDWR`.\n3. Сместим курсор на позицию 4: `file.Seek(4, io.SeekStart)`.\n4. Запишем строку `"XXXX"`.\n5. В `main` убедимся, что остальная часть файла не пострадала.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "in_place_edit.txt"\n\t_ = os.WriteFile(path, []byte("0123456789ABCDEF"), 0644)\n\n\t// Открываем на чтение и запись одновременно\n\tfile, err := os.OpenFile(path, os.O_RDWR, 0644)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer file.Close()\n\n\t// Смещаем курсор на позицию 5 (символ \'5\')\n\tif _, err := file.Seek(5, io.SeekStart); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\t// Записываем 4 символа поверх существующих\n\tif _, err := file.WriteString("XXXX"); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\t// Читаем файл с начала\n\tdata, _ := os.ReadFile(path)\n\tfmt.Printf("Исходный файл: 0123456789ABCDEF\\n")\n\tfmt.Printf("Результат:     %s\\n", string(data))\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Исходный файл: 0123456789ABCDEF\n# Результат:     01234XXXX9ABCDEF'}], 'under_the_hood': 'Запись в режиме `O_RDWR` перезаписывает только байты по текущему смещению курсора, сохраняя все последующие байты файла.', 'pitfalls': 'Не используйте флаг `os.O_TRUNC`, иначе файл будет очищен при открытии.', 'bigtech_interview': '**Вопрос с собеседования:** «Как работают embedded key-value базы вроде BoltDB / bbolt?»\n**Ответ:** Они открывают файл БД в режиме `O_RDWR` и отображают его в память через `mmap` (Memory-Mapped File). Запись страниц B+ дерева выполняется напрямую по вычисленным смещениям на диске.'}, {'num': 86, 'title': 'Создание глубокой структуры директорий data/logs/2026/07/ через os.MkdirAll', 'task': '**Создание вложенных директорий**: Используй `os.MkdirAll`, чтобы создать сложную структуру папок: `data/logs/2026/07/`.', 'theory': '`os.MkdirAll` создает путь любой глубины в один вызов, устанавливая права доступа `0755` ко всем созданным подкаталогам.', 'step_by_step': '1. Зададим глубокий путь `data/logs/2026/07`.\n2. Вызовем `os.MkdirAll(path, 0755)`.\n3. Создадим тестовый файл внутри самой глубокой папки.\n4. Проверим существование пути через `os.Stat`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n\t"path/filepath"\n)\n\nfunc main() {\n\ttargetDir := filepath.Join("data", "logs", "2026", "07")\n\n\tif err := os.MkdirAll(targetDir, 0755); err != nil {\n\t\tlog.Fatalf("Ошибка MkdirAll: %v", err)\n\t}\n\n\ttestFile := filepath.Join(targetDir, "access.log")\n\t_ = os.WriteFile(testFile, []byte("Log payload 2026"), 0644)\n\n\tinfo, err := os.Stat(testFile)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Успешно создана структура папок: %s\\n", targetDir)\n\tfmt.Printf("Файл внутри доступен: %s (%d байт)\\n", testFile, info.Size())\n\n\t_ = os.RemoveAll("data")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Успешно создана структура папок: data/logs/2026/07\n# Файл внутри доступен: data/logs/2026/07/access.log (16 байт)'}], 'under_the_hood': '`os.MkdirAll` использует системный вызов `mkdir` для каждого отсутствующего сегмента пути.', 'pitfalls': 'Убедитесь, что у процесса есть права на запись во все родительские директории.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если в пути MkdirAll один из промежуточных элементов уже существует как обычный файл, а не папка?»\n**Ответ:** `os.MkdirAll` вернет ошибку `syscall.ENOTDIR` (not a directory), так как нельзя создать директорию внутри существующего файла.'}, {'num': 87, 'title': 'Создание временного файла в системной папке Temp через os.CreateTemp', 'task': 'Временно создай файл в системной папке для временных файлов с помощью `os.CreateTemp`.', 'theory': 'Передача пустой строки `""` в первый аргумент `os.CreateTemp("", "pattern-*.ext")` автоматически выбирает системный каталог временных файлов (`os.TempDir()`, обычно `/tmp` в Linux и `%TEMP%` в Windows).', 'step_by_step': '1. Вызовем `tmpFile, err := os.CreateTemp("", "session-*.tmp")`.\n2. Установим `defer os.Remove(tmpFile.Name())` и `defer tmpFile.Close()`.\n3. Запишем временные данные.\n4. Выведем путь к файлу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\t// Пустая строка dir означает системную директорию os.TempDir()\n\ttmpFile, err := os.CreateTemp("", "session-payload-*.tmp")\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer os.Remove(tmpFile.Name())\n\tdefer tmpFile.Close()\n\n\tfmt.Printf("Временный файл создан в системной папке: %s\\n", tmpFile.Name())\n\n\tif _, err := tmpFile.WriteString("Encrypted auth token"); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tdata, _ := os.ReadFile(tmpFile.Name())\n\tfmt.Printf("Прочитано из временного файла: %s\\n", string(data))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Временный файл создан в системной папке: /tmp/session-payload-2983719284.tmp\n# Прочитано из временного файла: Encrypted auth token'}], 'under_the_hood': '`os.TempDir()` проверяет переменные окружения `$TMPDIR`, `$TMP`, `$TEMP`, `$USERPROFILE`, а в Unix возвращает `/tmp`.', 'pitfalls': 'В Linux `/tmp` часто монтируется как `tmpfs` в оперативной памяти (RAM). Запись гигантских файлов в `/tmp` может переполнить RAM.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему создание временного файла в /tmp безопасно от коллизий имен (Race Condition)?»\n**Ответ:** `os.CreateTemp` открывает файл с флагами `O_RDWR|O_CREATE|O_EXCL` и правами `0600`. Флаг `O_EXCL` на уровне ядра гарантирует атомарный отказ, если файл с таким именем уже существует, повторяя генерацию случайного имени.'}, {'num': 88, 'title': 'Красивая визуализация дерева файлов и каталогов с отступами', 'task': 'Напиши программу, которая рекурсивно обходит директорию (`filepath.Walk` или `filepath.WalkDir`). Выведи дерево файлов и папок с отступами.', 'theory': 'Иерархический вывод вычисляет уровень вложенности на основе количества разделителей `filepath.Separator` в относительном пути от корня.', 'step_by_step': '1. Создадим тестовую структуру директорий.\n2. Реализуем обход через `filepath.WalkDir`.\n3. Вычислим относительный путь через `filepath.Rel(root, path)`.\n4. Сформируем визуальный отступ `strings.Repeat("  ", depth)`.\n5. В `main` выведем дерево.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io/fs"\n\t"log"\n\t"os"\n\t"path/filepath"\n\t"strings"\n)\n\nfunc PrintTree(root string) error {\n\treturn filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif path == root {\n\t\t\tfmt.Printf("📦 %s/\\n", root)\n\t\t\treturn nil\n\t\t}\n\n\t\trel, _ := filepath.Rel(root, path)\n\t\tdepth := strings.Count(rel, string(filepath.Separator))\n\t\tindent := strings.Repeat("  ", depth)\n\n\t\tif d.IsDir() {\n\t\t\tfmt.Printf("%s📁 %s/\\n", indent, d.Name())\n\t\t} else {\n\t\t\tfmt.Printf("%s📄 %s\\n", indent, d.Name())\n\t\t}\n\t\treturn nil\n\t})\n}\n\nfunc main() {\n\troot := "sample_app"\n\t_ = os.MkdirAll(root+"/api/v1", 0755)\n\t_ = os.MkdirAll(root+"/configs", 0755)\n\t_ = os.WriteFile(root+"/main.go", []byte("package main"), 0644)\n\t_ = os.WriteFile(root+"/api/v1/router.go", []byte("package v1"), 0644)\n\t_ = os.WriteFile(root+"/configs/app.yaml", []byte("env: prod"), 0644)\n\n\tdefer os.RemoveAll(root)\n\n\tif err := PrintTree(root); err != nil {\n\t\tlog.Fatal(err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 📦 sample_app/\n# 📁 api/\n#   📁 v1/\n#     📄 router.go\n# 📁 configs/\n#   📄 app.yaml\n# 📄 main.go'}], 'under_the_hood': '`filepath.WalkDir` гарантирует обход каталогов в лексикографическом порядке.', 'pitfalls': 'Для исключения скрытых файлов добавьте проверку `if strings.HasPrefix(d.Name(), ".") { return nil }`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать утилиту tree на чистом Go?»\n**Ответ:** Использовать `filepath.WalkDir` с форматированием префиксов `├── ` и `└── ` на основе проверки последнего элемента в каталоге через `os.ReadDir`.'}, {'num': 89, 'title': 'Идиоматичный паттерн работы с временными файлами через os.CreateTemp', 'task': '**Временные файлы**: Используй `os.CreateTemp`, чтобы создать временный файл в системной `Temp` директории. Прочитай/запиши в него и добавь `defer os.Remove(tempFile.Name())`, чтобы он удалился после работы.', 'theory': 'Временные файлы используются для хранения промежуточных вычислений, кэширования больших результатов парсинга и безопасной атомарной записи на диск.', 'step_by_step': '1. Создадим временный файл `os.CreateTemp("", "worker-job-*.tmp")`.\n2. Добавим `defer os.Remove(f.Name())` и `defer f.Close()`.\n3. Запишем данные и прочитаем обратно.\n4. В `main` убедимся в удалении файла при выходе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc processTemporaryJob() error {\n\ttmp, err := os.CreateTemp("", "job-data-*.tmp")\n\tif err != nil {\n\t\treturn err\n\t}\n\tdefer os.Remove(tmp.Name())\n\tdefer tmp.Close()\n\n\tfmt.Printf("Создан временный файл: %s\\n", tmp.Name())\n\n\tif _, err := tmp.WriteString("Intermediate processing payload"); err != nil {\n\t\treturn err\n\t}\n\n\t// Читаем из временного файла\n\tdata, err := os.ReadFile(tmp.Name())\n\tif err != nil {\n\t\treturn err\n\t}\n\tfmt.Printf("Прочитано из временного файла: %s\\n", string(data))\n\n\treturn nil\n}\n\nfunc main() {\n\tif err := processTemporaryJob(); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tfmt.Println("Операция завершена, диск очищен")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Создан временный файл: /tmp/job-data-1928374615.tmp\n# Прочитано из временного файла: Intermediate processing payload\n# Операция завершена, диск очищен'}], 'under_the_hood': '`os.CreateTemp` генерирует случайный суффикс вместо `*` и открывает дескриптор с правами `0600`.', 'pitfalls': 'Порядок вызовов `defer`: сначала `os.Remove`, затем `f.Close()`. Так как `defer` выполняется в порядке LIFO, файл сначала закроется, а затем удалится.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в unit-тестах Go 1.14+ рекомендуют t.TempDir() вместо os.CreateTemp?»\n**Ответ:** `t.TempDir()` автоматически создает изолированный каталог для каждого теста и гарантированно удаляет его при завершении теста (даже при `t.FailNow()` или панике) через встроенный механизм `t.Cleanup()`.'}, {'num': 90, 'title': 'Поиск файлов по расширению и подсчет их суммарного размера', 'task': 'Напиши программу, которая находит все файлы с определённым расширением в директории и поддиректориях. Подсчитай их общий размер.', 'theory': 'Фильтрация по расширению `filepath.Ext(path) == targetExt` в сочетании с `d.Info()` позволяет агрегировать статистику файлов заданного типа (например, размер всех `.log` файлов).', 'step_by_step': '1. Создадим дерево файлов с расширениями `.log`, `.txt`, `.csv`.\n2. Реализуем функцию `FindAndSumBySize(root, ext string) (int64, []string, error)`.\n3. В `main` выведем список найденных файлов и их суммарный размер.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io/fs"\n\t"log"\n\t"os"\n\t"path/filepath"\n)\n\nfunc FindAndSumBySize(root, ext string) (int64, []string, error) {\n\tvar totalSize int64\n\tvar matches []string\n\n\terr := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif !d.IsDir() && filepath.Ext(path) == ext {\n\t\t\tinfo, err := d.Info()\n\t\t\tif err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t\ttotalSize += info.Size()\n\t\t\tmatches = append(matches, path)\n\t\t}\n\t\treturn nil\n\t})\n\n\treturn totalSize, matches, err\n}\n\nfunc main() {\n\troot := "log_archive"\n\t_ = os.MkdirAll(root+"/server1", 0755)\n\t_ = os.WriteFile(root+"/system.log", make([]byte, 2048), 0644)\n\t_ = os.WriteFile(root+"/server1/app.log", make([]byte, 4096), 0644)\n\t_ = os.WriteFile(root+"/server1/readme.md", []byte("docs"), 0644)\n\n\tdefer os.RemoveAll(root)\n\n\tsize, files, err := FindAndSumBySize(root, ".log")\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Найдено .log файлов: %d\\n", len(files))\n\tfor _, f := range files {\n\t\tfmt.Printf(" -> %s\\n", f)\n\t}\n\tfmt.Printf("Суммарный объем: %d байт (%.2f KB)\\n", size, float64(size)/1024)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Найдено .log файлов: 2\n#  -> log_archive/server1/app.log\n#  -> log_archive/system.log\n# Суммарный объем: 6144 байт (6.00 KB)'}], 'under_the_hood': '`filepath.Ext` возвращает расширение с ведущей точкой (например, `".log"`).', 'pitfalls': 'Сравнение расширений чувствительно к регистру в Linux (`.LOG` != `.log`). Для надежности используйте `strings.ToLower(filepath.Ext(path))`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать поиск по сложным glob паттернам (например *.2026-*.log)?»\n**Ответ:** Использовать функцию `filepath.Match(pattern, d.Name())` внутри `filepath.WalkDir`.'}, {'num': 91, 'title': 'Пропуск заголовка через file.Seek и вычитка оставшегося тела файла', 'task': '**Управление курсором (Seek)**: Открой файл. Используй `file.Seek`, чтобы пропустить первые 10 байт, а затем считай остальные.', 'theory': 'Пропуск фиксированного заголовка (`file.Seek(10, io.SeekStart)`) используется при парсинге контейнерных форматов (RIFF WAV, MP4, custom binary frames).', 'step_by_step': '1. Создадим файл с 10-байтным заголовком и полезной нагрузкой.\n2. Откроем файл через `os.Open`.\n3. Сместим курсор на 10 байт вперед через `file.Seek`.\n4. Вычитаем оставшиеся данные через `io.ReadAll`.\n5. В `main` убедимся, что прочитана только полезная нагрузка.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "frame.dat"\n\t// 10 байт заголовка "HEADER1234" + полезная нагрузка\n\tpayload := "HEADER1234Body payload data string"\n\t_ = os.WriteFile(path, []byte(payload), 0644)\n\n\tfile, err := os.Open(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer file.Close()\n\n\t// Пропускаем первые 10 байт заголовка\n\toffset, err := file.Seek(10, io.SeekStart)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tfmt.Printf("Курсор чтения установлен на смещение: %d байт\\n", offset)\n\n\tbody, err := io.ReadAll(file)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Прочитанное тело пакета: %q\\n", string(body))\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Курсор чтения установлен на смещение: 10 байт\n# Прочитанное тело пакета: "Body payload data string" '}], 'under_the_hood': '`file.Seek(10, io.SeekStart)` вызывает `lseek(fd, 10, SEEK_SET)`.', 'pitfalls': 'Если файл меньше 10 байт, `Seek` переместит курсор, но `io.ReadAll` вернет пустой срез и `EOF`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как пропустить N байт в объекте io.Reader без метода Seek (например, в сетевом сокете)?»\n**Ответ:** Использовать `io.CopyN(io.Discard, reader, N)`. Байты будут вычитаны из потока и безопасно отброшены.'}, {'num': 92, 'title': 'Бинарная сериализация структуры PlayerData в кодировке Little Endian', 'task': '**Бинарная запись**: Создайте структуру `PlayerData` с полями `ID uint32`, `Level uint16`, `Score float32`. Используя пакет `encoding/binary`, запишите эту структуру в файл `player.dat` в бинарном формате (в кодировке Little Endian).', 'theory': 'Бинарная сериализация структур с типами `uint32` (4B), `uint16` (2B) и `float32` (4B) упаковывает объект в компактный 10-байтный бинарный файл без форматирования строк.', 'step_by_step': '1. Объявим структуру `PlayerData struct { ID uint32; Level uint16; Score float32 }`.\n2. Создадим файл `player.dat`.\n3. Вызовем `binary.Write(file, binary.LittleEndian, player)`.\n4. Проверим размер полученного файла на диске (ровно 10 байт).', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/binary"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\ntype PlayerData struct {\n\tID    uint32  // 4 байта\n\tLevel uint16  // 2 байта\n\tScore float32 // 4 байта\n}\n\nfunc main() {\n\tpath := "player.dat"\n\tplayer := PlayerData{\n\t\tID:    1048576,\n\t\tLevel: 42,\n\t\tScore: 99.75,\n\t}\n\n\tfile, err := os.Create(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer file.Close()\n\n\tif err := binary.Write(file, binary.LittleEndian, player); err != nil {\n\t\tlog.Fatalf("Ошибка бинарной записи: %v", err)\n\t}\n\n\tinfo, _ := file.Stat()\n\tfmt.Printf("Структура PlayerData успешно сохранена в %s\\n", path)\n\tfmt.Printf("Размер бинарного файла на диске: %d байт (ровно 4+2+4)\\n", info.Size())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Структура PlayerData успешно сохранена в player.dat\n# Размер бинарного файла на диске: 10 байт (ровно 4+2+4)'}], 'under_the_hood': '`binary.Write` упаковывает `float32` по стандарту IEEE 754 в виде 4 байт `math.Float32bits`.', 'pitfalls': 'В `binary.Write` запрещено передавать типы с динамической длиной (`string`, `[]byte`).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему размер структуры в файле (10 байт) может отличаться от размера в оперативной памяти unsafe.Sizeof?»\n**Ответ:** Из-за выравнивания памяти процессора (Struct Memory Padding). В памяти 64-битной системы структура `PlayerData` может занимать 12 байт (2 байта паддинга после `Level`), но `binary.Write` упаковывает поля плотно без паддинга.'}, {'num': 93, 'title': 'Назначение временных файлов и гарантированная очистка через defer os.Remove', 'task': 'Напиши программу, которая создаёт временный файл (`os.CreateTemp`), пишет в него, а затем автоматически удаляет (`defer os.Remove`). Объясни, зачем нужны временные файлы.', 'theory': 'Назначение временных файлов:\n1. **Атомарная запись (Atomic Save):** запись во временный файл и последующий `os.Rename` исключают появление недописанных файлов при сбое.\n2. **Изоляция параллельных тестов:** каждый тест работает со своим уникальным файлом.\n3. **Разгрузка оперативной памяти (Offloading):** хранение многогигабайтных промежуточных результатов на диске.', 'step_by_step': '1. Создадим временный файл через `os.CreateTemp("", "analytics-*.tmp")`.\n2. Установим `defer os.Remove(f.Name())`.\n3. Запишем данные и закроем файл.\n4. В `main` убедимся в удалении файла.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc runOffloadedTask() {\n\t// Создаем временный файл в системной папке /tmp\n\ttmpFile, err := os.CreateTemp("", "bigdata-chunk-*.tmp")\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\ttmpName := tmpFile.Name()\n\tdefer os.Remove(tmpName) // Удаление при выходе\n\tdefer tmpFile.Close()    // Закрытие перед удалением\n\n\tfmt.Printf("[1] Создан временный буфер: %s\\n", tmpName)\n\n\t// Запись промежуточного результата\n\t_, _ = tmpFile.WriteString("Large interim aggregated dataset")\n\n\tfmt.Println("[2] Промежуточные вычисления успешно выполнены")\n}\n\nfunc main() {\n\trunOffloadedTask()\n\n\t// Проверка, что файл удален\n\tfmt.Println("[3] Выход из функции: временный файл гарантированно удален с диска")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [1] Создан временный буфер: /tmp/bigdata-chunk-819284719.tmp\n# [2] Промежуточные вычисления успешно выполнены\n# [3] Выход из функции: временный файл гарантированно удален с диска'}], 'under_the_hood': '`os.Remove` удаляет запись файла из директории ядра операционной системы.', 'pitfalls': 'Если программа завершится по сигналу `SIGKILL` (`kill -9`), `defer` не выполнится, и файл останется в `/tmp`. ОС периодически очищает `/tmp` через `systemd-tmpfiles`.', 'bigtech_interview': '**Вопрос с собеседования:** «Выполняются ли defer-функции при os.Exit(1) или log.Fatal()?\n**Ответ:** Нет! `os.Exit` немедленно завершает процесс через системный вызов `exit_group(2)`, минуя раскрутку стека и все зарегистрированные `defer` функции.'}, {'num': 94, 'title': 'Запись сырых бинарных данных int32 в формате LittleEndian', 'task': '**Запись бинарных данных**: Используй пакет `encoding/binary`. Создай слайс чисел типа `int32` и запиши их в файл как сырые байты в формате `LittleEndian` (`binary.Write`). Обрати внимание, что файл после этого нельзя нормально прочитать в обычном блокноте.', 'theory': 'Бинарный файл содержит машинные байты чисел. При открытии такого файла в текстовом редакторе байты отображаются как нечитаемые спецсимволы, так как они не являются печатными символами ASCII/UTF-8.', 'step_by_step': '1. Создадим срез `nums := []int32{0x00000041, 0x00000042, 0x00000043, 0x0000000A}`.\n2. Запишем в `binary.bin` через `binary.Write(f, binary.LittleEndian, nums)`.\n3. Прочитаем файл как строку и выведем шестнадцатеричный дамп.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/binary"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "raw_numbers.bin"\n\tnumbers := []int32{1, 256, 65536, 16777216}\n\n\tf, err := os.Create(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer f.Close()\n\n\tif err := binary.Write(f, binary.LittleEndian, numbers); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\trawBytes, _ := os.ReadFile(path)\n\tfmt.Printf("Файл записан (%d байт). Шестнадцатеричный дамп:\\n", len(rawBytes))\n\tfor i, b := range rawBytes {\n\t\tfmt.Printf("%02X ", b)\n\t\tif (i+1)%4 == 0 {\n\t\t\tfmt.Print("| ")\n\t\t}\n\t}\n\tfmt.Println()\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Файл записан (16 байт). Шестнадцатеричный дамп:\n# 01 00 00 00 | 00 01 00 00 | 00 00 01 00 | 00 00 00 01 |'}], 'under_the_hood': 'Число `256` (`0x00000100`) в Little Endian записывается как байты `00 01 00 00`.', 'pitfalls': 'Никогда не пытайтесь парсить бинарные файлы текстовым сканером `bufio.Scanner` — байт `0x0A` будет ошибочно воспринят как перевод строки `\\n`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество Protobuf/FlatBuffers перед сырым binary.Write?»\n**Ответ:** Protobuf поддерживает эволюцию схемы данных (добавление новых полей без поломки старых версий) и сжатие чисел (Varint/ZigZag), уменьшая размер сообщений в разы.'}, {'num': 95, 'title': 'Прямое бинарное восстановление структуры PlayerData через binary.Read', 'task': '**Бинарное чтение**: Откройте файл `player.dat`. Считайте из него бинарные данные напрямую в новую структуру `PlayerData` с помощью `binary.Read`. Выведите поля структуры, чтобы убедиться в правильности восстановления.', 'theory': '`binary.Read(r, binary.LittleEndian, &player)` вычитывает ровно необходимое количество байт из файла и декодирует их напрямую в поля структуры.', 'step_by_step': '1. Объявим структуру `PlayerData struct { ID uint32; Level uint16; Score float32 }`.\n2. Запишем тестовый бинарный файл `player.dat`.\n3. Откроем файл через `os.Open`.\n4. Вызовем `binary.Read(f, binary.LittleEndian, &restored)`.\n5. В `main` распечатаем восстановленные поля.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/binary"\n\t"fmt"\n\t"log"\n\t"os"\n)\n\ntype PlayerData struct {\n\tID    uint32\n\tLevel uint16\n\tScore float32\n}\n\nfunc main() {\n\tpath := "player.dat"\n\n\t// Подготовка данных\n\t_ = os.Remove(path)\n\tfOut, _ := os.Create(path)\n\t_ = binary.Write(fOut, binary.LittleEndian, PlayerData{ID: 777, Level: 99, Score: 1450.5})\n\tfOut.Close()\n\n\t// Бинарное чтение напрямую в структуру\n\tfIn, err := os.Open(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer fIn.Close()\n\n\tvar p PlayerData\n\tif err := binary.Read(fIn, binary.LittleEndian, &p); err != nil {\n\t\tlog.Fatalf("Ошибка binary.Read: %v", err)\n\t}\n\n\tfmt.Println("Структура успешно восстановлена из бинарного файла:")\n\tfmt.Printf(" -> Player ID: %d\\n", p.ID)\n\tfmt.Printf(" -> Level:     %d\\n", p.Level)\n\tfmt.Printf(" -> Score:     %.1f\\n", p.Score)\n\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Структура успешно восстановлена из бинарного файла:\n#  -> Player ID: 777\n#  -> Level:     99\n#  -> Score:     1450.5'}], 'under_the_hood': '`binary.Read` использует рефлексию для чтения байт в каждый адрес памяти структуры.', 'pitfalls': 'В `binary.Read` обязательно передавать указатель `&p`, иначе возникнет ошибка `binary.Read: non-pointer PlayerData`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как прочитать массив из 1000 структур PlayerData за один системный вызов?»\n**Ответ:** Передать указатель на срез `players := make([]PlayerData, 1000); binary.Read(f, binary.LittleEndian, &players)`.'}, {'num': 96, 'title': 'Построчный подсчет ошибок ERROR в лог-файле', 'task': 'Напиши функцию, которая читает лог-файл (текстовый) и возвращает количество строк, содержащих слово "ERROR".', 'theory': 'Построчный подсчет через `bufio.Scanner` и `strings.Contains` позволяет анализировать многогигабайтные лог-файлы с константной памятью $O(1)$.', 'step_by_step': '1. Создадим лог-файл `system.log`.\n2. Реализуем функцию `CountErrorLines(path string) (int, error)`.\n3. В цикле сканирования проверим `strings.Contains(scanner.Text(), "ERROR")`.\n4. В `main` выведем общее число сбоев.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"log"\n\t"os"\n\t"strings"\n)\n\nfunc CountErrorLines(path string) (int, error) {\n\tfile, err := os.Open(path)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tdefer file.Close()\n\n\tscanner := bufio.NewScanner(file)\n\tcount := 0\n\n\tfor scanner.Scan() {\n\t\tif strings.Contains(scanner.Text(), "ERROR") {\n\t\t\tcount++\n\t\t}\n\t}\n\n\treturn count, scanner.Err()\n}\n\nfunc main() {\n\tpath := "app_events.log"\n\tpayload := "INFO: app started\\nERROR: db timeout\\nWARN: high cpu\\nERROR: disk full\\nINFO: healthy"\n\t_ = os.WriteFile(path, []byte(payload), 0644)\n\n\terrCount, err := CountErrorLines(path)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Обнаружено строк с ошибками [ERROR]: %d\\n", errCount)\n\t_ = os.Remove(path)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обнаружено строк с ошибками [ERROR]: 2'}], 'under_the_hood': '`strings.Contains` выполняет быстрый поиск байтовой последовательности `ERROR`.', 'pitfalls': 'Используйте `scanner.Bytes()` и `bytes.Contains(scanner.Bytes(), []byte("ERROR"))` для нулевых аллокаций памяти.', 'bigtech_interview': '**Вопрос с собеседования:** «Как оптимизировать CountErrorLines для максимального throughput на NVMe SSD?»\n**Ответ:** Использовать `bytes.Count(chunk, []byte("\\nERROR"))` на блоках по 1MB или пакет `golang.org/x/sys/unix` с системным вызовом `mmap`.'}, {'num': 97, 'title': 'Мульти-дестинационный логгер с использованием io.MultiWriter', 'task': "Напиши программу, которая использует `io.MultiWriter` для одновременной записи в файл и в консоль. Напиши логгер, который пишет в несколько destination'ов.", 'theory': '`io.MultiWriter(w1, w2, ...)` дублирует каждую операцию записи во все переданные приемники `io.Writer`. Это стандартный способ в Go для одновременной записи логов в консоль (`os.Stdout`) и в файл на диске.', 'step_by_step': '1. Создадим файл `app_multi.log`.\n2. Создадим мульти-писатель `mw := io.MultiWriter(os.Stdout, logFile)`.\n3. Настроим стандартный логгер `log.SetOutput(mw)`.\n4. Запишем несколько логов и убедимся, что они появились в консоли и в файле.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tlogFilePath := "app_multi.log"\n\tfile, err := os.OpenFile(logFilePath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer file.Close()\n\n\t// Объединяем stdout и файл в единый MultiWriter\n\tmultiWriter := io.MultiWriter(os.Stdout, file)\n\n\t// Настраиваем стандартный логгер Go\n\tcustomLogger := log.New(multiWriter, "[AUDIT] ", log.Ldate|log.Ltime)\n\n\tcustomLogger.Println("Сервис успешно инициализирован")\n\tcustomLogger.Println("Подключение к брокеру Kafka установлено")\n\n\tfileData, _ := os.ReadFile(logFilePath)\n\tfmt.Printf("\\n--- Проверка содержимого файла %s ---\\n", logFilePath)\n\tfmt.Print(string(fileData))\n\n\t_ = os.Remove(logFilePath)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [AUDIT] 2026/09/02 18:30:00 Сервис успешно инициализирован\n# [AUDIT] 2026/09/02 18:30:00 Подключение к брокеру Kafka установлено\n# \n# --- Проверка содержимого файла app_multi.log ---\n# [AUDIT] 2026/09/02 18:30:00 Сервис успешно инициализирован\n# [AUDIT] 2026/09/02 18:30:00 Подключение к брокеру Kafka установлено'}], 'under_the_hood': '`io.MultiWriter` последовательно вызывает метод `Write` у каждого писателя. Если один из них возвращает ошибку, запись прерывается.', 'pitfalls': 'Если один из приемников медленный (например, сетевой сокет), `io.MultiWriter` заблокирует запись и во все остальные приемники.', 'bigtech_interview': '**Вопрос с собеседования:** «Как работает io.TeeReader?»\n**Ответ:** `io.TeeReader(r, w)` при чтении из `r` автоматически дублирует прочитанные байты в `w` (аналог Unix-утилиты `tee`).'}, {'num': 98, 'title': 'Финальный проект: CLI-утилита трансформации текста и подсчета слов', 'task': '**[Финальное испытание]**: Напиши CLI-утилиту, которая принимает флаг `-input` (путь к txt файлу) и `-output` (путь к новому файлу). Программа должна прочитать input, преобразовать весь текст в ВЕРХНИЙ РЕГИСТР, посчитать количество слов, и записать в output файл результат в формате: "WORDS: <count>\\nUPPERCASE TEXT: ...". Обработать все ошибки (нет файла, нет прав и т.д.) через `log.Fatalf`.', 'theory': 'Полноценная CLI-утилита использует пакет `flag` для парсинга аргументов командной строки, валидирует наличие файлов и прав доступа, выполняет преобразования и форматирует результат.', 'step_by_step': '1. Объявим флаги `flag.StringVar(&inputPath, "input", ...)` и `-output`.\n2. Вызовем `flag.Parse()`.\n3. Прочитаем входной файл и посчитаем слова.\n4. Преобразуем текст в `strings.ToUpper(text)`.\n5. Запишем форматированный отчет в выходной файл.\n6. В `main` протестируем работу CLI-конвейера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"flag"\n\t"fmt"\n\t"log"\n\t"os"\n\t"strings"\n)\n\nfunc runCLI(inputPath, outputPath string) {\n\tif inputPath == "" || outputPath == "" {\n\t\tlog.Fatalf("Ошибка: обязательны оба флага -input и -output")\n\t}\n\n\t// 1. Читаем исходный файл\n\tdata, err := os.ReadFile(inputPath)\n\tif err != nil {\n\t\tlog.Fatalf("Критическая ошибка чтения input файла %s: %v", inputPath, err)\n\t}\n\n\tcontent := string(data)\n\n\t// 2. Подсчет слов\n\tscanner := bufio.NewScanner(strings.NewReader(content))\n\tscanner.Split(bufio.ScanWords)\n\twordCount := 0\n\tfor scanner.Scan() {\n\t\twordCount++\n\t}\n\n\t// 3. Преобразование в верхний регистр\n\tupperContent := strings.ToUpper(content)\n\n\t// 4. Формирование вывода\n\tresult := fmt.Sprintf("WORDS: %d\\nUPPERCASE TEXT:\\n%s\\n", wordCount, upperContent)\n\n\t// 5. Запись в output файл\n\tif err := os.WriteFile(outputPath, []byte(result), 0644); err != nil {\n\t\tlog.Fatalf("Критическая ошибка записи в output файл %s: %v", outputPath, err)\n\t}\n\n\tfmt.Printf("Обработка завершена: %d слов записано в %s\\n", wordCount, outputPath)\n}\n\nfunc main() {\n\tinputFlag := flag.String("input", "input.txt", "Путь к исходному текстовому файлу")\n\toutputFlag := flag.String("output", "output.txt", "Путь к результирующему файлу")\n\tflag.Parse()\n\n\t// Демонстрационная подготовка тестового файла\n\t_ = os.WriteFile(*inputFlag, []byte("Go highload architecture and file processing engine"), 0644)\n\n\trunCLI(*inputFlag, *outputFlag)\n\n\tres, _ := os.ReadFile(*outputFlag)\n\tfmt.Println("--- Результат работы CLI ---")\n\tfmt.Print(string(res))\n\n\t_ = os.Remove(*inputFlag)\n\t_ = os.Remove(*outputFlag)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go -input input.txt -output output.txt\n# Вывод:\n# Обработка завершена: 7 слов записано в output.txt\n# --- Результат работы CLI ---\n# WORDS: 7\n# UPPERCASE TEXT:\n# GO HIGHLOAD ARCHITECTURE AND FILE PROCESSING ENGINE'}], 'under_the_hood': '`log.Fatalf` форматирует сообщение об ошибке, пишет его в `os.Stderr` и вызывает `os.Exit(1)`.', 'pitfalls': 'В юнит-тестах вместо `log.Fatalf` лучше возвращать `error`, чтобы тесты не падали аварийно.', 'bigtech_interview': '**Вопрос с собеседования:** «Как организовать структуру CLI-утилиты на Go по стандарту BigTech?»\n**Ответ:** Команды организуются в пакете `cmd/` с использованием библиотеки `spf13/cobra` и `spf13/viper`, а бизнес-логика выносится в пакет `internal/` с передачей зависимостей через интерфейсы.'}, {'num': 99, 'title': 'Временный файл конфигурации с автоматическим удалением перед выходом', 'task': '**Временные файлы**: Напишите программу, которая создает временный файл с помощью `os.CreateTemp`, записывает туда конфиг, читает его, а перед самым выходом из программы удаляет этот файл с диска с помощью `os.Remove`.', 'theory': 'Временные конфигурационные файлы применяются при запуске дочерних процессов (`os/exec`), требующих путь к файлу на диске (например, конфигурация `nginx -c /tmp/nginx-*.conf`).', 'step_by_step': '1. Создадим временный файл `os.CreateTemp("", "app-config-*.json")`.\n2. Установим `defer os.Remove(tmp.Name())`.\n3. Запишем JSON конфигурацию.\n4. Прочитаем конфигурацию.\n5. Убедимся в удалении файла при выходе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\ttmpConfig, err := os.CreateTemp("", "transient-cfg-*.json")\n\tif err != nil {\n\t\tlog.Fatalf("Ошибка создания временного файла: %v", err)\n\t}\n\tdefer os.Remove(tmpConfig.Name())\n\tdefer tmpConfig.Close()\n\n\tconfigJSON := `{"http_port": 8080, "log_level": "DEBUG", "enable_tls": true}`\n\tif _, err := tmpConfig.WriteString(configJSON); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Printf("Временный конфиг создан: %s\\n", tmpConfig.Name())\n\n\tdata, err := os.ReadFile(tmpConfig.Name())\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tfmt.Printf("Прочитан конфиг: %s\\n", string(data))\n\n\tfmt.Println("Выход из main: файл будет автоматически удален через defer os.Remove")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Временный конфиг создан: /tmp/transient-cfg-3819284719.json\n# Прочитан конфиг: {"http_port": 8080, "log_level": "DEBUG", "enable_tls": true}\n# Выход из main: файл будет автоматически удален через defer os.Remove'}], 'under_the_hood': '`os.CreateTemp` гарантирует уникальность имени и отсутствие конфликтов при одновременном запуске тысяч воркеров.', 'pitfalls': 'Не забывайте закрывать дескриптор `tmpConfig.Close()` перед вызовом `os.Remove`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как передать секретный конфиг процессу без сохранения на физический диск в Linux?»\n**Ответ:** Использовать системный вызов `memfd_create` (анонимный файл целиком в RAM) или смонтировать `tmpfs` RAM-диск.'}, {'num': 100, 'title': 'Реализация интерфейсов io.Reader и io.Writer для собственного типа MemoryBuffer', 'task': 'Напиши программу, которая реализует `io.Reader` и `io.Writer` для кастомного типа (например, `type MemoryBuffer struct { data []byte }`). Реализуй методы `Read` и `Write` по интерфейсам.', 'theory': 'Реализация стандартных интерфейсов `io.Reader` и `io.Writer` делает кастомный тип совместимым со всей стандартной библиотекой Go (`io.Copy`, `bufio`, `json.NewDecoder`, `http.Post`, `crypto/sha256`).', 'step_by_step': '1. Объявим `type MemoryBuffer struct { buf []byte; offset int }`.\n2. Реализуем метод `Write(p []byte) (n int, err error)`.\n3. Реализуем метод `Read(p []byte) (n int, err error)`.\n4. В `main` проверим совместимость с `io.Copy` и `fmt.Fprintf`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n)\n\ntype MemoryBuffer struct {\n\tbuf    []byte\n\toffset int\n}\n\nfunc NewMemoryBuffer() *MemoryBuffer {\n\treturn &MemoryBuffer{buf: make([]byte, 0, 128)}\n}\n\n// Реализация io.Writer: дописывает данные в конец буфера\nfunc (m *MemoryBuffer) Write(p []byte) (n int, err error) {\n\tm.buf = append(m.buf, p...)\n\treturn len(p), nil\n}\n\n// Реализация io.Reader: читает данные с текущей позиции offset до io.EOF\nfunc (m *MemoryBuffer) Read(p []byte) (n int, err error) {\n\tif m.offset >= len(m.buf) {\n\t\treturn 0, io.EOF\n\t}\n\tn = copy(p, m.buf[m.offset:])\n\tm.offset += n\n\treturn n, nil\n}\n\nfunc main() {\n\tmem := NewMemoryBuffer()\n\n\t// 1. Запись через fmt.Fprintf (интерфейс io.Writer)\n\tfmt.Fprintf(mem, "Item #%d: %s\\n", 1, "HighLoad Architecture")\n\tfmt.Fprintf(mem, "Item #%d: %s\\n", 2, "Custom io.ReadWriter Implementation")\n\n\t// 2. Чтение через io.ReadAll (интерфейс io.Reader)\n\tresult, err := io.ReadAll(mem)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\n\tfmt.Println("--- Данные из кастомного MemoryBuffer ---")\n\tfmt.Print(string(result))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Данные из кастомного MemoryBuffer ---\n# Item #1: HighLoad Architecture\n# Item #2: Custom io.ReadWriter Implementation'}], 'under_the_hood': 'Интерфейсы в Go удовлетворяются неявно (duck typing). Наличие методов `Read` и `Write` автоматически делает `*MemoryBuffer` реализацией интерфейса `io.ReadWriter`.', 'pitfalls': 'Обязательно возвращайте `io.EOF`, когда `m.offset >= len(m.buf)`, иначе `io.ReadAll` зависнет в бесконечном цикле!', 'bigtech_interview': '**Вопрос с собеседования:** «Почему io.Reader и io.Writer являются главными интерфейсами всей экосистемы Go?»\n**Ответ:** Потому что они абстрагируют ввод-вывод: файлу, сокету TCP, HTTP-запросу, zip-архиву, SHA256-хэшеру и буферу памяти все равно, с кем работать. Любой `io.Reader` можно передать в любой `io.Writer` через `io.Copy`, формируя гибкие конвейеры обработки данных.'}]
